-- CreateEnum
CREATE TYPE "PromoCategory" AS ENUM ('RESERVATION', 'REGISTRATION');

-- AlterTable
ALTER TABLE "Reservation" ADD COLUMN     "promoCodeId" TEXT;

-- CreateTable
CREATE TABLE "PromoCode" (
    "id" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "category" "PromoCategory" NOT NULL DEFAULT 'RESERVATION',
    "startDate" DATE NOT NULL,
    "endDate" DATE NOT NULL,
    "expirationDate" DATE,
    "discountType" "DiscountType" NOT NULL,
    "discountValue" DECIMAL(10,2) NOT NULL,
    "kmDiscountType" "DiscountType",
    "kmDiscountValue" DECIMAL(10,2),
    "minDays" INTEGER NOT NULL DEFAULT 1,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "autoApply" BOOLEAN NOT NULL DEFAULT true,
    "oneTimeUse" BOOLEAN NOT NULL DEFAULT false,
    "locationIds" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "vehicleTypeIds" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "PromoCode_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "PromoCode_code_key" ON "PromoCode"("code");

-- AddForeignKey
ALTER TABLE "Reservation" ADD CONSTRAINT "Reservation_promoCodeId_fkey" FOREIGN KEY ("promoCodeId") REFERENCES "PromoCode"("id") ON DELETE SET NULL ON UPDATE CASCADE;


